  75% { opacity: 1; transform: scale(1); }
  80% { opacity: 0; transform: scale(1); }
  100% { opacity: 0; transform: scale(1); }
}
.anim-cuadradito {
  animation: llenarBucle 4s infinite;
  opacity: 0;
}
</style>

